create unique index if not exists payments_reference_uidx on public.payments(reference) where reference is not null and reference<>''; create index if not exists payment_requests_related_payment_idx on public.payment_requests(related_payment_id); create index if not exists orders_payment_reference_idx on public.orders(payment_reference); create or replace function public.resolve_payment_order(_payment_request_id uuid) returns public.orders language plpgsql security definer set search_path=public as $$ declare p public.payment_requests; pay_ref text; o public.orders; begin select * into p from public.payment_requests where id=_payment_request_id; if p.id is null then return null; end if; if p.related_payment_id is not null then select reference into pay_ref from public.payments where id=p.related_payment_id; if pay_ref is not null then select * into o from public.orders where payment_reference=pay_ref limit 1; if o.id is not null then return o; end if; end if; end if; select * into o from public.orders where payment_reference=p.reference limit 1; return o; end; $$; revoke all on function public.resolve_payment_order(uuid) from public; grant execute on function public.resolve_payment_order(uuid) to authenticated;
